const S = (name, code, description) => ({ name, type: 'SQL', code, description });
const AI = "COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{tema}}', '%')";
const FINS = `COALESCE(NULLIF(P.FINALIDADES, ''), CONCAT_WS(',', IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'lucid|clareza|discernimento|concentra|foco|aten[cç][aã]o|mente (calma|tranquila|serena)', 'lucidez', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'depress|ansied|tristez|ang[uú]sti|medo|p[aâ]nico|emo[cç]|ang[uú]stia', 'emocional', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'negativ|mau.{0,10}pensamento|forma.?pensamento|pessimis|pensamentos? ruins?', 'negativos', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'prote|limpeza|descarrego|escudo|blind|purifica', 'protecao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'obsess|ataque|vampiri|feiti|demanda|magia negra|esp[ií]ritos? (sofredor|trevoso|baixo)', 'obsessao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'dormir|sono|ins[oô]nia|deitar|adormec', 'sono', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'proje[cç][aã]o|desdobramento|sonho l[uú]cido|sa[ií]da do corpo|extraf[ií]sic', 'projecao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'sa[uú]de|cura|doen|dores? |imunid|corpo f[ií]sico', 'saude', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'prosper|dinheiro|abund[aâ]ncia|abrir caminhos|abertura de caminhos|emprego', 'prosperidade', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'perd[aã]o|perdoar|fam[ií]lia|relacion|casal|filhos? |m[aá]goa', 'relacoes', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP ' casa |ambiente| lar |c[oô]modos?|resid[eê]ncia', 'casa', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'mentor|amparador|conex[aã]o|gratid[aã]o|intui[cç]|mediun', 'conexao', NULL)))`;
const FILTRO_P = `V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%'))`;
export const tela = [
  S('inicioVideosNovos', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.THUMB, LEFT(V.RESUMO, 240) RESUMO, C.NOME CANAL FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' ORDER BY V.PUBLICADO_EM DESC, V.ID DESC LIMIT 6`, 'Início: últimos vídeos estudados'),
  S('inicioParaAssistir', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.THUMB, C.NOME CANAL FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.FAVORITO = 1 AND V.ASSISTIDO_EM IS NULL AND V.STATUS <> 'FORA' ORDER BY V.PUBLICADO_EM DESC LIMIT 6`, 'Início: favoritos que ainda não assisti'),
  S('inicioLivroUltimo', `SELECT TEMA_ID, TEMA, GERADO_EM, LEFT(TEXTO, 420) TRECHO, (SELECT COUNT(*) FROM LIVRO_CAPITULOS) N FROM LIVRO_CAPITULOS ORDER BY GERADO_EM DESC LIMIT 1`, 'Início: último capítulo do Livro Vivo'),
  S('inicioPraticaDia', `SELECT P.ID, P.TIPO, P.JEITO, P.SERVE, P.QUANDO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND CHAR_LENGTH(P.INSTRUCAO) > 40 AND ('{{fin}}' = '' OR FIND_IN_SET('{{fin}}', P.SERVE) OR CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{fin}}', '.%')) ORDER BY CRC32(CONCAT(P.ID, '-', '{{dia}}', '-', {{vez}})) LIMIT 1`, 'Início: uma prática sorteada para o dia, pelo que ela serve'),
  S('praticasJeitos', `SELECT P.JEITO COD, COUNT(*) QTD FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{serve}}' = '' OR FIND_IN_SET('{{serve}}', P.SERVE) OR (LOCATE('.', '{{serve}}') = 0 AND CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{serve}}', '.%'))) AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) GROUP BY P.JEITO`, 'Práticas: quantas há em cada jeito de fazer'),
  S('praticasServe', `SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(P.SERVE, ',', K.N), ',', -1) COD, COUNT(*) QTD FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN (SELECT 1 N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) K ON K.N <= 1 + LENGTH(P.SERVE) - LENGTH(REPLACE(P.SERVE, ',', '')) WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{jeito}}' = '' OR P.JEITO = '{{jeito}}') AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) AND P.SERVE IS NOT NULL GROUP BY COD`, 'Práticas: quantas servem para cada coisa, dentro do jeito de fazer'),
  S('praticasQuando', `SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(P.QUANDO, ',', K.N), ',', -1) COD, COUNT(*) QTD FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN (SELECT 1 N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) K ON K.N <= 1 + LENGTH(P.QUANDO) - LENGTH(REPLACE(P.QUANDO, ',', '')) WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{jeito}}' = '' OR P.JEITO = '{{jeito}}') AND ('{{serve}}' = '' OR FIND_IN_SET('{{serve}}', P.SERVE) OR (LOCATE('.', '{{serve}}') = 0 AND CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{serve}}', '.%'))) AND P.QUANDO IS NOT NULL GROUP BY COD`, 'Práticas: quantas há para cada momento de fazer'),
  S('praticasLista', `SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.SERVE, P.QUANDO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND P.CONSELHO = 0 AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ({{fav}} = 0 OR P.FAVORITA = 1) AND ('{{jeito}}' = '' OR P.JEITO = '{{jeito}}') AND ('{{serve}}' = '' OR FIND_IN_SET('{{serve}}', P.SERVE) OR (LOCATE('.', '{{serve}}') = 0 AND CONCAT(',', P.SERVE) LIKE CONCAT('%,', '{{serve}}', '.%'))) AND ('{{quando}}' = '' OR FIND_IN_SET('{{quando}}', P.QUANDO)) ORDER BY V.PUBLICADO_EM DESC, P.ID LIMIT {{limit}} OFFSET {{offset}}`, 'Práticas com passo a passo, por jeito de fazer, para que serve e quando'),
  S('praticasTotais', `SELECT SUM(P.CONSELHO = 0) N, SUM(P.REVISADA_EM IS NOT NULL AND P.CONSELHO = 0) MARCADAS, SUM(P.REVISADA_EM IS NULL) FALTAM FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE V.STATUS = 'ESTUDADO'`, 'Quantas práticas há e quantas já estão organizadas'),
  S('playlistsListar', `SELECT P.ID, P.TITULO, P.CANAL_ID, C.NOME CANAL, P.QTD_YT, COUNT(V.ID) QTD, SUM(V.STATUS = 'ESTUDADO') ESTUDADOS FROM PLAYLISTS P JOIN CANAIS C ON C.ID = P.CANAL_ID JOIN PLAYLIST_VIDEOS PV ON PV.PLAYLIST_ID = P.ID JOIN VIDEOS V ON V.YT_VIDEO_ID = PV.YT_VIDEO_ID WHERE V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY P.ID, P.TITULO, P.CANAL_ID, C.NOME, P.QTD_YT, P.ORDEM ORDER BY P.CANAL_ID, P.ORDEM`, 'Playlists com quantos vídeos sobram nos filtros escolhidos'),
  S('canalPorYt', `SELECT ID, NOME FROM CANAIS WHERE YT_CHANNEL_ID = '{{yt}}'`, 'Canal pelo id do YouTube'),
  S('canalInserir', `INSERT IGNORE INTO CANAIS (YT_CHANNEL_ID, HANDLE, NOME, URL, UPLOADS_PLAYLIST, THUMB, CARGA_STATUS, CARGA_MSG, CRIADO_EM) VALUES ('{{yt}}', '{{handle}}', '{{nome}}', '{{url}}', '{{uploads}}', '{{thumb}}', 'LISTANDO', 'Levantando os vídeos do canal', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s'))`, 'Cadastra canal'),
  S('canaisListar', `SELECT C.ID, C.NOME, C.HANDLE, C.URL, C.THUMB, C.CARGA_STATUS, C.CARGA_MSG, C.ULTIMA_CHECAGEM, C.CRIADO_EM, SUM(V.STATUS = 'ESTUDADO') ESTUDADOS, SUM(V.STATUS = 'FILA') FILA, SUM(V.STATUS = 'PENDENTE') PENDENTES, SUM(V.STATUS = 'FILA' AND V.ORIGEM = 'AUDIO') SEM_LEGENDA, SUM(V.STATUS <> 'FORA') TOTAL FROM CANAIS C LEFT JOIN VIDEOS V ON V.CANAL_ID = C.ID GROUP BY C.ID, C.NOME, C.HANDLE, C.URL, C.THUMB, C.CARGA_STATUS, C.CARGA_MSG, C.ULTIMA_CHECAGEM, C.CRIADO_EM ORDER BY C.ID`, 'Canais com contagens'),
  S('painelResumo', `SELECT SUM(STATUS = 'ESTUDADO') ESTUDADOS, SUM(STATUS = 'FILA') FILA, SUM(STATUS = 'PENDENTE') PENDENTES, SUM(STATUS = 'FORA_TEMA') FORA_TEMA, 0 TEMAS FROM VIDEOS V WHERE ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})`, 'Números gerais'),
  S('videosListar', `SELECT V.ID, V.FAVORITO, V.ASSISTIDO_EM, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.TIPO, V.THUMB, V.STATUS, V.MOTIVO, V.ORIGEM, V.INDISPONIVEL, V.TENTATIVAS, C.NOME CANAL, (SELECT GROUP_CONCAT(T.NOME ORDER BY T.NOME SEPARATOR '|') FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = V.ID) TEMAS, (SELECT GROUP_CONCAT(DISTINCT P.TITULO ORDER BY P.ORDEM SEPARATOR '|') FROM PLAYLIST_VIDEOS PV JOIN PLAYLISTS P ON P.ID = PV.PLAYLIST_ID WHERE PV.YT_VIDEO_ID = V.YT_VIDEO_ID) PLAYLISTS, (SELECT GROUP_CONCAT(DISTINCT PR.TIPO ORDER BY PR.TIPO SEPARATOR '|') FROM PRATICAS PR WHERE PR.VIDEO_ID = V.ID) PRATICAS FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') AND ('{{meu}}' = '' OR ('{{meu}}' = 'FAV' AND V.FAVORITO = 1) OR ('{{meu}}' = 'VISTO' AND V.ASSISTIDO_EM IS NOT NULL) OR ('{{meu}}' = 'NAOVISTO' AND V.ASSISTIDO_EM IS NULL)) ORDER BY CASE WHEN {{nPlay}} = 1 THEN (SELECT MIN(PX.POS) FROM PLAYLIST_VIDEOS PX WHERE PX.PLAYLIST_ID = '{{playlists}}' AND PX.YT_VIDEO_ID = V.YT_VIDEO_ID) END ASC, CASE WHEN V.STATUS = 'ESTUDADO' THEN 0 ELSE 1 END, V.PUBLICADO_EM DESC, V.ORDEM DESC LIMIT {{limit}} OFFSET {{offset}}`, 'Lista de vídeos com filtros combinados (temas, playlists e práticas)'),
  S('temasListar', `SELECT T.ID, T.NOME, COUNT(*) QTD FROM TEMAS T JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID WHERE T.NOME NOT LIKE 'mentor: %' AND V.STATUS IN ('ESTUDADO', 'FORA_TEMA') AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY T.ID, T.NOME ORDER BY QTD DESC, T.NOME LIMIT 500`, 'Temas com quantos vídeos sobram nos filtros escolhidos'),
  S('mentoresListar', `SELECT T.ID, SUBSTRING(T.NOME, 9) NOME, COUNT(*) QTD FROM TEMAS T JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID WHERE T.NOME LIKE 'mentor: %' AND V.STATUS IN ('ESTUDADO', 'FORA_TEMA') AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY T.ID, T.NOME ORDER BY QTD DESC, T.NOME LIMIT 500`, 'Mentores com quantos vídeos sobram nos filtros escolhidos'),
  S('videoDetalhe', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.TIPO, V.THUMB, V.STATUS, V.MOTIVO, V.ORIGEM, V.INDISPONIVEL, V.RESUMO, V.ESTUDADO_EM, V.TEMAS_EDITADOS, V.FAVORITO, V.ASSISTIDO_EM, C.NOME CANAL FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.ID = {{id}}`, 'Detalhe do vídeo'),
  S('videoTemas', `SELECT T.ID, T.NOME, VT.ORIGEM, VT.MOMENTOS FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = {{videoId}} ORDER BY T.NOME`, 'Temas de um vídeo'),
  S('temaGarantir', `INSERT IGNORE INTO TEMAS (NOME) VALUES ('{{nome}}')`, 'Cria tema'),
  S('vtAcrescentar', `INSERT INTO VIDEO_TEMAS (VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS) SELECT {{videoId}}, ID, 'USUARIO', '' FROM TEMAS WHERE NOME = '{{nome}}' ON DUPLICATE KEY UPDATE ORIGEM = 'USUARIO'`, 'Acrescenta tema'),
  S('vtTirar', `DELETE FROM VIDEO_TEMAS WHERE VIDEO_ID = {{videoId}} AND TEMA_ID = {{temaId}}`, 'Tira tema'),
  S('vtRenomear', `UPDATE IGNORE VIDEO_TEMAS SET TEMA_ID = (SELECT ID FROM TEMAS WHERE NOME = '{{nome}}'), ORIGEM = 'USUARIO' WHERE VIDEO_ID = {{videoId}} AND TEMA_ID = {{temaId}}`, 'Renomeia tema do vídeo'),
  S('vtTirarSeOutro', `DELETE FROM VIDEO_TEMAS WHERE VIDEO_ID = {{videoId}} AND TEMA_ID = {{temaId}} AND TEMA_ID <> (SELECT ID FROM TEMAS WHERE NOME = '{{nome}}')`, 'Limpa tema antigo após renomear'),
  S('videoForaTema', `UPDATE VIDEOS SET STATUS = CASE WHEN {{fora}} = 1 THEN 'FORA_TEMA' ELSE 'ESTUDADO' END, MOTIVO = CASE WHEN {{fora}} = 1 THEN 'Marcado por você como fora do tema espiritualidade.' ELSE NULL END WHERE ID = {{id}} AND STATUS IN ('ESTUDADO', 'FORA_TEMA')`, 'Põe ou tira o vídeo da área Fora do tema'),
  S('videoMarcarEditado', `UPDATE VIDEOS SET TEMAS_EDITADOS = 1 WHERE ID = {{id}}`, 'Marca temas editados pela dona'),
  S('buscarTema', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.TIPO, V.THUMB, V.INDISPONIVEL, V.ORIGEM, C.NOME CANAL, X.SCORE, X.NT, X.MOMS FROM (SELECT VIDEO_ID, SUM(P) SCORE, SUM(P = 1) NT, GROUP_CONCAT(M SEPARATOR ',') MOMS FROM (SELECT VT.VIDEO_ID, 10 P, VT.MOMENTOS M FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE T.NOME ${AI} UNION ALL SELECT TR.VIDEO_ID, 1 P, CAST(TR.SEGUNDO AS CHAR) M FROM TRECHOS TR WHERE TR.TEXTO ${AI}) U GROUP BY VIDEO_ID) X JOIN VIDEOS V ON V.ID = X.VIDEO_ID AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) JOIN CANAIS C ON C.ID = V.CANAL_ID ORDER BY CASE WHEN '{{ordem}}' = 'recentes' THEN V.PUBLICADO_EM END DESC, X.SCORE DESC, V.PUBLICADO_EM DESC LIMIT {{limit}} OFFSET {{offset}}`, 'Busca por tema (relevância ou recentes)'),
  S('buscaTrechos', `SELECT V.TITULO, TR.SEGUNDO, TR.TEXTO FROM TRECHOS TR JOIN VIDEOS V ON V.ID = TR.VIDEO_ID AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) WHERE TR.TEXTO ${AI} ORDER BY TR.VIDEO_ID, TR.SEGUNDO LIMIT 80`, 'Trechos que citam o tema'),
  S('buscaResumos', `SELECT DISTINCT V.TITULO, V.RESUMO FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID AND V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) WHERE T.NOME ${AI} LIMIT 20`, 'Resumos dos vídeos do tema'),
  S('avisosListar', `SELECT ID, DIA, CRIADO_EM, QTD, LIDO, LIDO_EM FROM AVISOS WHERE QTD > 0 AND ARQUIVADO = 0 ORDER BY ID DESC LIMIT 30`, 'Avisos de vídeos novos'),
  S('avisoVideos', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.STATUS, C.NOME CANAL FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.AVISO_ID = {{id}} ORDER BY V.PUBLICADO_EM DESC`, 'Vídeos do aviso'),
  S('avisoMarcar', `UPDATE AVISOS SET LIDO = {{lido}}, LIDO_EM = CASE WHEN {{lido}} = 1 THEN DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') ELSE NULL END WHERE ID = {{id}}`, 'Marca aviso como lido (1) ou não lido (0)'),
  S('avisoArquivar', `UPDATE AVISOS SET ARQUIVADO = 1, LIDO = TRUE, LIDO_EM = IFNULL(LIDO_EM, DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) WHERE ID = {{id}}`, 'Arquiva aviso: sai da lista'),
  S('avisosTodosLidos', `UPDATE AVISOS SET LIDO = TRUE, LIDO_EM = DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') WHERE LIDO = FALSE AND ARQUIVADO = 0`, 'Marca todos os avisos como lidos'),
  S('avisoMarcarLido', `UPDATE AVISOS SET LIDO = TRUE, LIDO_EM = DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') WHERE ID = {{id}} AND LIDO = FALSE`, 'Marca aviso como lido'),
  S('motorAndamento', `SELECT VALOR LOCK_ATE FROM CONFIG WHERE CHAVE = 'LOCK'`, 'Se o motor está rodando'),
  S('canaisLimiteMais', `UPDATE CANAIS SET LIMITE = (SELECT COUNT(*) FROM VIDEOS V WHERE V.CANAL_ID = CANAIS.ID) + {{qtd}}, CARGA_STATUS = 'LISTANDO', CARGA_TOKEN = '', POS_BASE = 0, ELEGIVEIS = 0, CARGA_MSG = 'Levantando mais {{qtd}} vídeos do canal' WHERE {{canalId}} = 0 OR ID = {{canalId}}`, 'Libera mais vídeos para estudar'),
  S('canaisNomes', `SELECT ID, NOME, HANDLE FROM CANAIS ORDER BY ID`, 'Nomes dos canais'),
  S('estudoAndamento', `SELECT C.ID, C.NOME, SUM(V.STATUS = 'ESTUDADO') ESTUDADOS, SUM(V.STATUS = 'FILA') FILA, SUM(V.STATUS = 'PENDENTE') PENDENTES, SUM(V.STATUS = 'FILA' AND V.ORIGEM = 'AUDIO') SEM_LEGENDA FROM CANAIS C LEFT JOIN VIDEOS V ON V.CANAL_ID = C.ID GROUP BY C.ID, C.NOME ORDER BY C.ID`, 'Andamento do estudo por canal'),
  S('exportVideos', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.ORIGEM, C.NOME CANAL, V.RESUMO, (SELECT GROUP_CONCAT(CONCAT(T.NOME, '=', IFNULL(VT.MOMENTOS, '')) ORDER BY T.NOME SEPARATOR '|') FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = V.ID) TEMAS FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND V.ID > {{depois}} ORDER BY V.ID LIMIT 500`, 'Exportação: vídeos estudados com resumo e temas'),
  S('exportTrechos', `SELECT T.VIDEO_ID, T.SEGUNDO, T.TEXTO FROM TRECHOS T JOIN VIDEOS V ON V.ID = T.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND (T.VIDEO_ID > {{video}} OR (T.VIDEO_ID = {{video}} AND T.SEGUNDO > {{segundo}})) ORDER BY T.VIDEO_ID, T.SEGUNDO LIMIT 5000`, 'Exportação: trechos das transcrições, em páginas'),
  S('exportEstrutura', `SELECT TABLE_NAME, COLUMN_NAME, COLUMN_TYPE, IS_NULLABLE, COLUMN_KEY, COLUMN_DEFAULT, EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('CANAIS','VIDEOS','TRECHOS','TEMAS','VIDEO_TEMAS','PLAYLISTS','PLAYLIST_VIDEOS','AVISOS','CONFIG','PRATICAS','MENTOR_REGRAS','LOTES','LIVRO_CAPITULOS') ORDER BY TABLE_NAME, ORDINAL_POSITION`, 'Estrutura das tabelas para exportar'),
  S('exportIndices', `SELECT TABLE_NAME, INDEX_NAME, NON_UNIQUE, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) COLUNAS FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('CANAIS','VIDEOS','TRECHOS','TEMAS','VIDEO_TEMAS','PLAYLISTS','PLAYLIST_VIDEOS','AVISOS','CONFIG','PRATICAS','MENTOR_REGRAS','LOTES','LIVRO_CAPITULOS') GROUP BY TABLE_NAME, INDEX_NAME, NON_UNIQUE ORDER BY TABLE_NAME, INDEX_NAME`, 'Índices das tabelas para exportar'),
  S('exportTabCanais', `SELECT * FROM CANAIS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta CANAIS'),
  S('exportTabVideos', `SELECT ID, CANAL_ID, YT_VIDEO_ID, TITULO, PUBLICADO_EM, DURACAO_SEG, TIPO, THUMB, STATUS, MOTIVO, ORIGEM, PROGRESSO_SEG, TENTATIVAS, RESUMO, INDISPONIVEL, ESTUDADO_EM, ATUALIZADO_EM, AVISO_ID, CRIADO_EM, PRIORIDADE, ORDEM, DESCOBERTA, TEMAS_EDITADOS, PRATICAS_EM FROM VIDEOS WHERE ID > {{depois}} ORDER BY ID LIMIT 2000`, 'Exporta VIDEOS'),
  S('exportTabTrechos', `SELECT ID, VIDEO_ID, SEGUNDO, TEXTO FROM TRECHOS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta TRECHOS'),
  S('exportTabTemas', `SELECT ID, NOME FROM TEMAS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta TEMAS'),
  S('exportTabVideoTemas', `SELECT ID, VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS, VERIFICADO FROM VIDEO_TEMAS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta VIDEO_TEMAS'),
  S('exportTabPlaylists', `SELECT * FROM PLAYLISTS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta PLAYLISTS'),
  S('exportTabPlaylistVideos', `SELECT ID, PLAYLIST_ID, YT_VIDEO_ID, POS FROM PLAYLIST_VIDEOS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta PLAYLIST_VIDEOS'),
  S('exportTabAvisos', `SELECT * FROM AVISOS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta AVISOS'),
  S('exportVideosFiltro', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.ORIGEM, V.STATUS, C.NOME CANAL, V.RESUMO, (SELECT GROUP_CONCAT(CONCAT(T.NOME, '=', IFNULL(VT.MOMENTOS, '')) ORDER BY T.NOME SEPARATOR '|') FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = V.ID) TEMAS, (SELECT GROUP_CONCAT(DISTINCT P.TITULO ORDER BY P.ORDEM SEPARATOR ' | ') FROM PLAYLIST_VIDEOS PV JOIN PLAYLISTS P ON P.ID = PV.PLAYLIST_ID WHERE PV.YT_VIDEO_ID = V.YT_VIDEO_ID) PLAYLISTS, (SELECT GROUP_CONCAT(CONCAT(PR.TIPO, ': ', IFNULL(PR.TITULO, '')) ORDER BY PR.SEGUNDO SEPARATOR ' | ') FROM PRATICAS PR WHERE PR.VIDEO_ID = V.ID) PRATICAS FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') AND ('{{meu}}' = '' OR ('{{meu}}' = 'FAV' AND V.FAVORITO = 1) OR ('{{meu}}' = 'VISTO' AND V.ASSISTIDO_EM IS NOT NULL) OR ('{{meu}}' = 'NAOVISTO' AND V.ASSISTIDO_EM IS NULL)) AND V.ID > {{depois}} ORDER BY V.ID LIMIT 500`, 'Exportação: vídeos com os filtros da tela Vídeos e temas'),
  S('praticasTipos', `SELECT XR2.JEITO TIPO, COUNT(DISTINCT XR2.VIDEO_ID) QTD FROM PRATICAS XR2 JOIN VIDEOS V ON V.ID = XR2.VIDEO_ID WHERE XR2.CONSELHO = 0 AND V.STATUS <> 'FORA' AND (V.STATUS <> 'FORA_TEMA' OR '{{status}}' = 'FORA_TEMA') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{status}}' = '' OR V.STATUS = '{{status}}') AND ({{nTemas}} = 0 OR V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE FIND_IN_SET(XT.TEMA_ID, '{{temas}}') GROUP BY XT.VIDEO_ID HAVING COUNT(DISTINCT XT.TEMA_ID) = {{nTemas}})) AND ({{nPlay}} = 0 OR V.YT_VIDEO_ID IN (SELECT XP.YT_VIDEO_ID FROM PLAYLIST_VIDEOS XP WHERE FIND_IN_SET(XP.PLAYLIST_ID, '{{playlists}}') GROUP BY XP.YT_VIDEO_ID HAVING COUNT(DISTINCT XP.PLAYLIST_ID) = {{nPlay}})) AND ({{nPrat}} = 0 OR V.ID IN (SELECT XR.VIDEO_ID FROM PRATICAS XR WHERE XR.CONSELHO = 0 AND FIND_IN_SET(XR.JEITO, '{{praticas}}') GROUP BY XR.VIDEO_ID HAVING COUNT(DISTINCT XR.JEITO) = {{nPrat}})) AND ('{{origem}}' = '' OR V.ORIGEM = '{{origem}}') GROUP BY XR2.JEITO ORDER BY QTD DESC, XR2.JEITO`, 'Tipos de prática com quantos vídeos sobram nos filtros escolhidos'),
  S('praticasDoVideo', `SELECT ID, TIPO, JEITO, SERVE, QUANDO, TITULO, INSTRUCAO, SEGUNDO FROM PRATICAS WHERE VIDEO_ID = {{videoId}} AND CONSELHO = 0 ORDER BY SEGUNDO, ID`, 'Práticas ensinadas num vídeo'),
  S('iaEstado', `SELECT (SELECT VALOR FROM CONFIG WHERE CHAVE = 'IA_PAUSADA_ATE') PAUSADA_ATE, COUNT(*) N, SUM(PRATICAS_EM IS NOT NULL) LIDOS FROM VIDEOS WHERE STATUS = 'ESTUDADO'`, 'Se a IA está pausada pela cota e quantos vídeos já foram lidos para práticas'),
  S('praticasResumo', `SELECT COUNT(*) N, SUM(PRATICAS_EM IS NOT NULL) LIDOS FROM VIDEOS WHERE STATUS = 'ESTUDADO'`, 'Quantos vídeos estudados já foram lidos para práticas'),
  S('exportTabMentorRegras', `SELECT ID, NOME, TIPO, DESTINO, CRIADO_EM FROM MENTOR_REGRAS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta MENTOR_REGRAS'),
  S('exportVisoes', `SELECT TABLE_NAME, VIEW_DEFINITION FROM information_schema.VIEWS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME LIKE 'VW_LOTE_%' ORDER BY TABLE_NAME`, 'Visões de lote para exportar'),
  S('exportTabPraticas', `SELECT * FROM PRATICAS WHERE ID > {{depois}} ORDER BY ID LIMIT 5000`, 'Exporta PRATICAS'),
  S('exportTabConfig', `SELECT CHAVE, VALOR FROM CONFIG WHERE CHAVE <> 'LOCK' ORDER BY CHAVE`, 'Exporta CONFIG'),
  S('mentoresGerir', `SELECT T.ID, SUBSTRING(T.NOME, 9) NOME, COUNT(VT.ID) QTD FROM TEMAS T LEFT JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID WHERE T.NOME LIKE 'mentor: %' GROUP BY T.ID, T.NOME HAVING QTD > 0 OR SUBSTRING(T.NOME, 9) IN (SELECT NOME FROM MENTOR_REGRAS WHERE TIPO = 'MENTOR') ORDER BY QTD DESC, NOME`, 'Mentores com quantos vídeos têm, para a tela de gestão'),
  S('configTelaLer', `SELECT CHAVE, VALOR FROM CONFIG WHERE CHAVE IN ('DURACAO_MIN_SEG', 'HORA_CHECAGEM', 'AUDIO_LIGADO', 'PRATICAS_LIGADO', 'CONFERIR_MENTOR', 'FINALIDADE_LIGADO', 'LIVRO_LIGADO', 'LIVRO_POR_NOITE', 'LIVRO_PAUSA_ATE', 'IA_PAUSADA_ATE', 'VALIDAR_LIVROS')`, 'Ajustes do estudo que a tela mostra'),
  S('configTelaGravar', `INSERT INTO CONFIG (CHAVE, VALOR) VALUES ('{{chave}}', '{{valor}}') ON DUPLICATE KEY UPDATE VALOR = VALUES(VALOR)`, 'Grava um ajuste do estudo'),
  S('canaisMentorLer', `SELECT ID, NOME, TEM_MENTOR FROM CANAIS ORDER BY ID`, 'Canais e se o estudo procura mentor neles'),
  S('canalMentorGravar', `UPDATE CANAIS SET TEM_MENTOR = {{tem}} WHERE ID = {{id}}`, 'Liga ou desliga a busca de mentor no canal'),
  S('mentorRegrasListar', `SELECT ID, NOME, TIPO, DESTINO, CRIADO_EM FROM MENTOR_REGRAS ORDER BY TIPO, NOME`, 'Regras de mentores que o estudo segue'),
  S('mentorVideos', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, VT.ORIGEM FROM VIDEO_TEMAS VT JOIN VIDEOS V ON V.ID = VT.VIDEO_ID WHERE VT.TEMA_ID = {{temaId}} ORDER BY V.PUBLICADO_EM DESC LIMIT 300`, 'Vídeos de um mentor'),
  S('mentorRegraGravar', `INSERT INTO MENTOR_REGRAS (NOME, TIPO, DESTINO, CRIADO_EM) VALUES ('{{nome}}', '{{tipo}}', NULLIF('{{destino}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) ON DUPLICATE KEY UPDATE TIPO = VALUES(TIPO), DESTINO = VALUES(DESTINO)`, 'Grava regra de mentor'),
  S('mentorRegraApagar', `DELETE FROM MENTOR_REGRAS WHERE ID = {{id}}`, 'Apaga regra de mentor'),
  S('mentorRegraApagarNome', `DELETE FROM MENTOR_REGRAS WHERE NOME = '{{nome}}'`, 'Apaga regra de mentor pelo nome'),
  S('mentorTemaPorId', `SELECT ID, SUBSTRING(NOME, 9) NOME FROM TEMAS WHERE ID = {{id}} AND NOME LIKE 'mentor: %'`, 'Mentor pelo id'),
  S('mentorTemaPorNome', `SELECT ID, SUBSTRING(NOME, 9) NOME FROM TEMAS WHERE NOME = '{{nome}}'`, 'Mentor pelo nome completo'),
  S('mentorBackup', `INSERT IGNORE INTO VIDEO_TEMAS_BKP_MENTORES (ID, VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS) SELECT ID, VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS FROM VIDEO_TEMAS WHERE TEMA_ID = {{temaId}}`, 'Cópia de segurança das ligações de um mentor'),
  S('mentorMover', `UPDATE IGNORE VIDEO_TEMAS SET TEMA_ID = {{destino}} WHERE TEMA_ID = {{origem}}`, 'Passa os vídeos de um mentor para outro'),
  S('mentorDesligar', `DELETE FROM VIDEO_TEMAS WHERE TEMA_ID = {{temaId}}`, 'Tira um mentor de todos os vídeos'),
  S('mentorTemaApagar', `DELETE FROM TEMAS WHERE ID = {{temaId}} AND NOME LIKE 'mentor: %'`, 'Apaga o mentor'),
  S('mentorTemaRenomear', `UPDATE TEMAS SET NOME = '{{nome}}' WHERE ID = {{temaId}} AND NOME LIKE 'mentor: %'`, 'Renomeia o mentor'),
  S('mentorMarcarTitulos', `INSERT IGNORE INTO VIDEO_TEMAS (VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS) SELECT V.ID, {{temaId}}, 'USUARIO', '' FROM VIDEOS V WHERE V.STATUS = 'ESTUDADO' AND V.TITULO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{nome}}', '%')`, 'Marca o mentor nos vídeos com o nome dele no título'),
  S('mentorRegrasMotor', `SELECT NOME, TIPO, DESTINO FROM MENTOR_REGRAS`, 'Regras de mentores para o motor'),
  S('mentorConferirFila', `SELECT VT.ID, VT.VIDEO_ID, SUBSTRING(T.NOME, 9) MENTOR, V.TITULO FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID WHERE T.NOME LIKE 'mentor: %' AND VT.VERIFICADO IS NULL AND VT.ORIGEM = 'IA' ORDER BY VT.ID LIMIT 1`, 'Próximo mentor marcado pela IA que falta conferir na transcrição'),
  S('mentorConferirContar', `SELECT COUNT(*) N FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE T.NOME LIKE 'mentor: %' AND VT.VERIFICADO IS NULL AND VT.ORIGEM = 'IA'`, 'Quantos mentores faltam conferir'),
  S('mentorConferido', `UPDATE VIDEO_TEMAS SET VERIFICADO = 1 WHERE ID = {{id}}`, 'Marca mentor como conferido'),
  S('mentorDescartarBkp', `INSERT IGNORE INTO VIDEO_TEMAS_BKP_MENTORES (ID, VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS) SELECT ID, VIDEO_ID, TEMA_ID, ORIGEM, MOMENTOS FROM VIDEO_TEMAS WHERE ID = {{id}}`, 'Cópia antes de tirar mentor que não conduz'),
  S('mentorDescartar', `DELETE FROM VIDEO_TEMAS WHERE ID = {{id}}`, 'Tira mentor que não conduz a live'),
  S('videoMentoresVerificados', `UPDATE VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID SET VT.VERIFICADO = 1 WHERE VT.VIDEO_ID = {{videoId}} AND T.NOME LIKE 'mentor: %'`, 'Mentores do vídeo já conferidos no estudo'),
  S('livroTemas', `SELECT T.ID, T.NOME, COUNT(DISTINCT V.ID) QTD, COUNT(DISTINCT V.CANAL_ID) CANAIS, MAX(L.GERADO_EM) GERADO_EM FROM TEMAS T JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID AND V.STATUS = 'ESTUDADO' LEFT JOIN LIVRO_CAPITULOS L ON L.TEMA_ID = T.ID WHERE T.NOME NOT LIKE 'mentor: %' GROUP BY T.ID, T.NOME HAVING QTD >= 5 ORDER BY QTD DESC LIMIT 400`, 'Livro Vivo: temas e se já têm capítulo'),
  S('livroCapitulo', `SELECT TEMA_ID, TEMA, TEXTO, PRATICAS_JSON, VIDEOS, GERADO_EM FROM LIVRO_CAPITULOS WHERE TEMA_ID = {{temaId}}`, 'Livro Vivo: um capítulo'),
  S('exportTabLivro', `SELECT * FROM LIVRO_CAPITULOS WHERE ID > {{depois}} ORDER BY ID LIMIT 200`, 'Exporta LIVRO_CAPITULOS'),
  S('praticaFavorito', `UPDATE PRATICAS SET FAVORITA = {{fav}} WHERE ID = {{id}}`, 'Marca ou desmarca a prática como favorita'),
  S('praticasFavoritas', `SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA, (SELECT ROUND(AVG(D.HUMOR), 1) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) HUMOR FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE P.FAVORITA = 1 ORDER BY P.TITULO LIMIT 200`, 'Minhas práticas: as favoritas'),
  S('praticaTrechos', `SELECT SEGUNDO, TEXTO FROM TRECHOS WHERE VIDEO_ID = {{videoId}} AND SEGUNDO BETWEEN {{de}} AND {{ate}} ORDER BY SEGUNDO LIMIT 60`, 'Trechos da transcrição perto do ponto onde a prática é ensinada'),
  S('praticaUma', `SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE P.ID = {{id}}`, 'Uma prática com o vídeo de onde veio'),
  S('videoFavorito', `UPDATE VIDEOS SET FAVORITO = {{fav}} WHERE ID = {{id}}`, 'Marca ou desmarca o vídeo como favorito'),
  S('videoAssistido', `UPDATE VIDEOS SET ASSISTIDO_EM = CASE WHEN {{visto}} = 1 THEN DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') ELSE NULL END WHERE ID = {{id}}`, 'Marca ou desmarca o vídeo como já assistido'),
  S('meusContar', `SELECT SUM(FAVORITO = 1) FAV, SUM(ASSISTIDO_EM IS NOT NULL) VISTOS FROM VIDEOS WHERE STATUS <> 'FORA' AND ({{canalId}} = 0 OR CANAL_ID = {{canalId}})`, 'Quantos vídeos são favoritos e quantos já foram assistidos'),
  S('diarioInserir', `INSERT INTO PRATICA_DIARIO (PRATICA_ID, DIA, HUMOR, SENTIU, CRIADO_EM) SELECT ID, '{{dia}}', NULLIF({{humor}}, 0), NULLIF('{{sentiu}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM PRATICAS WHERE ID = {{praticaId}}`, 'Minhas práticas: registra que fiz e como me senti'),
  S('diarioUltimo', `SELECT D.ID, D.DIA, D.HUMOR, D.SENTIU, (SELECT COUNT(*) FROM PRATICA_DIARIO X WHERE X.PRATICA_ID = {{praticaId}}) VEZES, (SELECT MAX(X.DIA) FROM PRATICA_DIARIO X WHERE X.PRATICA_ID = {{praticaId}}) ULTIMA FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = {{praticaId}} ORDER BY D.ID DESC LIMIT 1`, 'Minhas práticas: o registro recém-criado e o novo total da prática'),
  S('diarioContagem', `SELECT COUNT(*) VEZES, MAX(DIA) ULTIMA FROM PRATICA_DIARIO WHERE PRATICA_ID = {{praticaId}}`, 'Minhas práticas: quantas vezes e a última data de uma prática'),
  S('diarioAtualizar', `UPDATE PRATICA_DIARIO SET DIA = '{{dia}}', HUMOR = NULLIF({{humor}}, 0), SENTIU = NULLIF('{{sentiu}}', '') WHERE ID = {{id}}`, 'Minhas práticas: edita um registro'),
  S('diarioUm', `SELECT ID, PRATICA_ID FROM PRATICA_DIARIO WHERE ID = {{id}}`, 'Minhas práticas: um registro'),
  S('diarioApagarUltimo', `DELETE FROM PRATICA_DIARIO WHERE PRATICA_ID = {{praticaId}} ORDER BY ID DESC LIMIT 1`, 'Minhas práticas: desfaz o último registro de uma prática'),
  S('diarioApagar', `DELETE FROM PRATICA_DIARIO WHERE ID = {{id}}`, 'Minhas práticas: apaga um registro'),
  S('diarioListar', `SELECT D.ID, D.PRATICA_ID, D.DIA, D.HUMOR, D.SENTIU, P.TIPO, P.JEITO, P.TITULO, P.SEGUNDO, V.YT_VIDEO_ID, C.NOME CANAL FROM PRATICA_DIARIO D JOIN PRATICAS P ON P.ID = D.PRATICA_ID JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE ({{praticaId}} = 0 OR D.PRATICA_ID = {{praticaId}}) ORDER BY D.DIA DESC, D.ID DESC LIMIT {{limit}} OFFSET {{offset}}`, 'Minhas práticas: o que fiz e como me senti'),
  S('diarioPraticas', `SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, COUNT(*) VEZES, MAX(D.DIA) ULTIMA, ROUND(AVG(D.HUMOR), 1) HUMOR FROM PRATICA_DIARIO D JOIN PRATICAS P ON P.ID = D.PRATICA_ID JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID GROUP BY P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID, V.YT_VIDEO_ID, V.TITULO, C.NOME ORDER BY MAX(D.DIA) DESC, COUNT(*) DESC LIMIT 100`, 'Minhas práticas: as que já fiz, quantas vezes e como me senti em média'),
  S('diarioResumo', `SELECT COUNT(*) VEZES, COUNT(DISTINCT PRATICA_ID) PRATICAS, COUNT(DISTINCT DIA) DIAS, SUM(DIA >= DATE_FORMAT(NOW() - INTERVAL 3 HOUR - INTERVAL 6 DAY, '%Y-%m-%d')) SEMANA, ROUND(AVG(HUMOR), 1) HUMOR FROM PRATICA_DIARIO`, 'Minhas práticas: números gerais'),
  S('livroProximo', `SELECT T.ID, T.NOME, COUNT(DISTINCT V.ID) QTD FROM TEMAS T JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID AND V.STATUS = 'ESTUDADO' LEFT JOIN LIVRO_CAPITULOS L ON L.TEMA_ID = T.ID WHERE T.NOME NOT LIKE 'mentor: %' AND L.TEMA_ID IS NULL GROUP BY T.ID, T.NOME HAVING QTD >= 5 ORDER BY QTD DESC LIMIT 1`, 'Livro Vivo: o próximo capítulo a escrever sozinho'),
  S('livroHoje', `SELECT COUNT(*) N FROM LIVRO_CAPITULOS WHERE GERADO_EM >= '{{dia}}'`, 'Livro Vivo: quantos capítulos foram escritos desde um dia'),
  S('pendLista', `SELECT N.ID, N.NOME, N.SUGESTAO_TITULO, N.SUGESTAO_AUTOR, N.MOTIVO, (SELECT COUNT(DISTINCT L.VIDEO_ID) FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME) VIDEOS FROM LIVROS_NOMES N WHERE N.ESTADO = 'PENDENTE' ORDER BY VIDEOS DESC, N.NOME LIMIT 30`, 'Nomes de livros que a busca não confirmou, para a pessoa decidir'),
  S('pendTotal', `SELECT COUNT(*) N FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE'`, 'Quantos nomes de livros aguardam decisão'),
  S('pendCatalogoCriar', `INSERT INTO LIVROS_CATALOGO (TITULO, AUTOR, CRIADO_EM) VALUES ('{{titulo}}', NULLIF('{{autor}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) ON DUPLICATE KEY UPDATE AUTOR = COALESCE(AUTOR, NULLIF('{{autor}}', ''))`, 'Cadastra um livro confirmado no catálogo'),
  S('pendDecidir', `UPDATE LIVROS_NOMES N JOIN LIVROS_CATALOGO C ON C.TITULO = '{{titulo}}' SET N.CATALOGO_ID = C.ID, N.ESTADO = 'OK' WHERE N.ID = {{id}}`, 'Liga um nome ouvido a um livro do catálogo'),
  S('pendNaoLivro', `UPDATE LIVROS_NOMES SET ESTADO = 'NAO_LIVRO', CATALOGO_ID = NULL WHERE ID = {{id}}`, 'Marca um nome como não sendo livro'),
  S('validarLista', `SELECT MIN(L.ID) ID, MIN(L.TITULO) NOME, MAX(NULLIF(L.AUTOR, '')) AUTOR, COUNT(DISTINCT L.VIDEO_ID) VIDEOS, MAX(N.ID) NID, MAX(N.SUGESTAO_TITULO) SUG_TITULO, MAX(N.SUGESTAO_AUTOR) SUG_AUTOR, MAX(N.MOTIVO) MOTIVO, MAX(N.CERTEZA) CERTEZA, MAX(N.TIPO_SUG) TIPO FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE (N.ID IS NULL OR N.ESTADO = 'PENDENTE') AND ('{{busca}}' = '' OR L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{tipo}}' = '' OR ('{{tipo}}' = 'semtipo' AND N.TIPO_SUG IS NULL) OR N.TIPO_SUG = '{{tipo}}') AND ('{{origem}}' = '' OR ('{{origem}}' = 'claude' AND N.CONFERIDO = 'IMPORTADO') OR ('{{origem}}' = 'app' AND N.ID IS NOT NULL AND COALESCE(N.CONFERIDO, '') <> 'IMPORTADO')) AND ('{{faixa}}' = '' OR ('{{faixa}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{faixa}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90)) AND ('{{grupo}}' <> '1' OR N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G)) AND ('{{filtro}}' = '' OR ('{{filtro}}' = 'sug' AND N.ID IS NOT NULL) OR ('{{filtro}}' = 'novo' AND N.ID IS NULL) OR ('{{filtro}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{filtro}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90) OR ('{{filtro}}' IN ('novoautor', 'novosolo') AND N.ID IS NULL) OR '{{filtro}}' = 'semautor' OR ('{{filtro}}' = 'grupo' AND N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G))) GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci HAVING ('{{campos}}' = '' OR ('{{campos}}' = 'ambos' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'titulo' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL)) OR ('{{campos}}' = 'autor' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'nenhum' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL))) AND ('{{filtro}}' <> 'novoautor' OR MAX(NULLIF(L.AUTOR, '')) IS NOT NULL) AND ('{{filtro}}' <> 'semautor' OR (MAX(NULLIF(L.AUTOR, '')) IS NULL AND MAX(NULLIF(N.SUGESTAO_AUTOR, '')) IS NULL)) AND ('{{filtro}}' <> 'novosolo' OR MAX(NULLIF(L.AUTOR, '')) IS NULL) ORDER BY IF('{{grupo}}' = '1', MAX(N.SUGESTAO_TITULO), '') ASC, (MAX(N.ID) IS NOT NULL) DESC, MAX(N.CERTEZA) DESC, VIDEOS DESC, NOME LIMIT {{limit}} OFFSET {{offset}}`, 'Nomes de livros que ainda precisam de validação'),
  S('validarAltaTotal', `SELECT COUNT(*) N FROM LIVROS_NOMES N WHERE N.ESTADO = 'PENDENTE' AND N.CERTEZA >= 90 AND EXISTS (SELECT 1 FROM LIVROS_CATALOGO C WHERE C.TITULO COLLATE utf8mb4_0900_ai_ci = N.SUGESTAO_TITULO COLLATE utf8mb4_0900_ai_ci)`, 'Quantas sugestões com 90% ou mais de certeza podem ser aceitas em massa'),
  S('validarAceitarAlta', `UPDATE LIVROS_NOMES N SET N.CATALOGO_ID = (SELECT MIN(C.ID) FROM LIVROS_CATALOGO C WHERE C.TITULO COLLATE utf8mb4_0900_ai_ci = N.SUGESTAO_TITULO COLLATE utf8mb4_0900_ai_ci), N.ESTADO = 'OK', N.MOTIVO = 'Aceito em massa (certeza de 90% ou mais)' WHERE N.ESTADO = 'PENDENTE' AND N.CERTEZA >= 90 AND EXISTS (SELECT 1 FROM LIVROS_CATALOGO C WHERE C.TITULO COLLATE utf8mb4_0900_ai_ci = N.SUGESTAO_TITULO COLLATE utf8mb4_0900_ai_ci)`, 'Aceita em massa as sugestões com 90% ou mais de certeza'),
  S('validarTotal', `SELECT COUNT(DISTINCT L.TITULO COLLATE utf8mb4_0900_ai_ci) N, COUNT(DISTINCT CASE WHEN N.ID IS NOT NULL THEN L.TITULO COLLATE utf8mb4_0900_ai_ci END) PEND, COUNT(DISTINCT CASE WHEN N.ID IS NULL AND NULLIF(L.AUTOR, '') IS NOT NULL THEN L.TITULO COLLATE utf8mb4_0900_ai_ci END) COM_AUTOR FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE N.ID IS NULL OR N.ESTADO = 'PENDENTE'`, 'Quantos nomes de livros aguardam validação'),
  S('catalogoBusca', `SELECT ID, TITULO, AUTOR FROM LIVROS_CATALOGO WHERE '{{busca}}' <> '' AND CONCAT(TITULO, ' ', COALESCE(AUTOR, '')) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%') ORDER BY TITULO LIMIT 8`, 'Procura um livro no catálogo (biblioteca)'),
  S('livroCatDe', `SELECT X.TITULO NOME, N.CATALOGO_ID CAT, C.TITULO, C.AUTOR FROM LIVROS_INDICADOS X LEFT JOIN LIVROS_NOMES N ON N.NOME = X.TITULO COLLATE utf8mb4_0900_ai_ci AND N.ESTADO = 'OK' LEFT JOIN LIVROS_CATALOGO C ON C.ID = N.CATALOGO_ID WHERE X.ID = {{id}}`, 'Qual livro do catálogo está ligado a uma indicação'),
  S('livroCatOutro', `SELECT ID FROM LIVROS_CATALOGO WHERE TITULO COLLATE utf8mb4_0900_ai_ci = '{{titulo}}' AND ID <> {{catId}} LIMIT 1`, 'Outro livro do catálogo com o mesmo título'),
  S('livroCatEditar', `UPDATE LIVROS_CATALOGO SET TITULO = '{{titulo}}', AUTOR = NULLIF('{{autor}}', '') WHERE ID = {{catId}}`, 'Corrige título e autor de um livro do catálogo'),
  S('livroStatusGravar', `UPDATE LIVROS_CATALOGO SET STATUS_LEITURA = NULLIF('{{status}}', '') WHERE ID = {{catId}}`, 'Marca se o livro foi lido, está sendo lido, está na biblioteca ou é desejado'),
  S('catalogoAchar', `SELECT ID FROM LIVROS_CATALOGO WHERE REPLACE(TITULO, '''', '') COLLATE utf8mb4_0900_ai_ci = '{{titulo}}' LIMIT 1`, 'Acha o livro do catálogo pelo título'),
  S('nomeOkCat', `INSERT INTO LIVROS_NOMES (NOME, CATALOGO_ID, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, {{catId}}, 'OK', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE CATALOGO_ID = VALUES(CATALOGO_ID), ESTADO = 'OK', MOTIVO = VALUES(MOTIVO)`, 'Liga um nome ouvido a um livro do catálogo'),
  S('validarExportar', `SELECT MIN(L.TITULO) NOME, MAX(NULLIF(L.AUTOR, '')) AUTOR, COUNT(DISTINCT L.VIDEO_ID) VIDEOS, MAX(LEFT(L.TRECHO, 300)) TRECHO, MAX(N.SUGESTAO_TITULO) SUG_TITULO, MAX(N.SUGESTAO_AUTOR) SUG_AUTOR, MAX(N.CERTEZA) CERTEZA, MAX(N.MOTIVO) MOTIVO, MAX(N.TIPO_SUG) TIPO FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE (N.ID IS NULL OR N.ESTADO = 'PENDENTE') AND ('{{busca}}' = '' OR L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{tipo}}' = '' OR ('{{tipo}}' = 'semtipo' AND N.TIPO_SUG IS NULL) OR N.TIPO_SUG = '{{tipo}}') AND ('{{origem}}' = '' OR ('{{origem}}' = 'claude' AND N.CONFERIDO = 'IMPORTADO') OR ('{{origem}}' = 'app' AND N.ID IS NOT NULL AND COALESCE(N.CONFERIDO, '') <> 'IMPORTADO')) AND ('{{faixa}}' = '' OR ('{{faixa}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{faixa}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90)) AND ('{{grupo}}' <> '1' OR N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G)) AND ('{{filtro}}' = '' OR ('{{filtro}}' = 'sug' AND N.ID IS NOT NULL) OR ('{{filtro}}' = 'novo' AND N.ID IS NULL) OR ('{{filtro}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{filtro}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90) OR ('{{filtro}}' IN ('novoautor', 'novosolo') AND N.ID IS NULL) OR '{{filtro}}' = 'semautor' OR ('{{filtro}}' = 'grupo' AND N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G))) GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci HAVING ('{{campos}}' = '' OR ('{{campos}}' = 'ambos' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'titulo' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL)) OR ('{{campos}}' = 'autor' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'nenhum' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL))) AND ('{{filtro}}' <> 'novoautor' OR MAX(NULLIF(L.AUTOR, '')) IS NOT NULL) AND ('{{filtro}}' <> 'semautor' OR (MAX(NULLIF(L.AUTOR, '')) IS NULL AND MAX(NULLIF(N.SUGESTAO_AUTOR, '')) IS NULL)) AND ('{{filtro}}' <> 'novosolo' OR MAX(NULLIF(L.AUTOR, '')) IS NULL) ORDER BY VIDEOS DESC, NOME LIMIT {{limit}} OFFSET {{offset}}`, 'Pendentes de validação para exportar'),
  S('validarSugerir', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, SUGESTAO_TITULO, SUGESTAO_AUTOR, CERTEZA, MOTIVO, CONFERIDO, TIPO_SUG, SUBTIPO, CRIADO_EM) VALUES ('{{nome}}', 'PENDENTE', NULLIF(LEFT('{{titulo}}', 300), ''), NULLIF(LEFT('{{autor}}', 200), ''), {{certeza}}, LEFT('{{motivo}}', 300), 'IMPORTADO', NULLIF('{{tipo}}', ''), NULLIF('{{subtipo}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) ON DUPLICATE KEY UPDATE SUGESTAO_TITULO = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_TITULO), SUGESTAO_TITULO), SUGESTAO_AUTOR = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_AUTOR), SUGESTAO_AUTOR), CERTEZA = IF(ESTADO = 'PENDENTE', VALUES(CERTEZA), CERTEZA), MOTIVO = IF(ESTADO = 'PENDENTE', VALUES(MOTIVO), MOTIVO), CONFERIDO = IF(ESTADO = 'PENDENTE', 'IMPORTADO', CONFERIDO), TIPO_SUG = IF(ESTADO = 'PENDENTE', VALUES(TIPO_SUG), TIPO_SUG), SUBTIPO = IF(ESTADO = 'PENDENTE', VALUES(SUBTIPO), SUBTIPO)`, 'Grava uma sugestão vinda de fora, sem aprovar nada'),
  S('validarSugerirEsp', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, SUGESTAO_TITULO, SUGESTAO_AUTOR, CERTEZA, MOTIVO, CONFERIDO, TIPO_SUG, SUBTIPO, CRIADO_EM) SELECT L.TITULO, 'PENDENTE', NULLIF(LEFT('{{titulo}}', 300), ''), NULLIF(LEFT('{{autor}}', 200), ''), {{certeza}}, LEFT('{{motivo}}', 300), 'IMPORTADO', NULLIF('{{tipo}}', ''), NULLIF('{{subtipo}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE '{{padrao}}' GROUP BY L.TITULO LIMIT 1 ON DUPLICATE KEY UPDATE SUGESTAO_TITULO = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_TITULO), SUGESTAO_TITULO), SUGESTAO_AUTOR = IF(ESTADO = 'PENDENTE', VALUES(SUGESTAO_AUTOR), SUGESTAO_AUTOR), CERTEZA = IF(ESTADO = 'PENDENTE', VALUES(CERTEZA), CERTEZA), MOTIVO = IF(ESTADO = 'PENDENTE', VALUES(MOTIVO), MOTIVO), CONFERIDO = IF(ESTADO = 'PENDENTE', 'IMPORTADO', CONFERIDO), TIPO_SUG = IF(ESTADO = 'PENDENTE', VALUES(TIPO_SUG), TIPO_SUG), SUBTIPO = IF(ESTADO = 'PENDENTE', VALUES(SUBTIPO), SUBTIPO)`, 'Grava sugestão vinda de fora para nomes com aspas ou barras'),
  S('nomeNaoLivro', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, 'NAO_LIVRO', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE ESTADO = 'NAO_LIVRO', CATALOGO_ID = NULL, MOTIVO = VALUES(MOTIVO)`, 'Marca um nome como não sendo livro'),
  S('validarOnde', `SELECT L.ID, L.SEGUNDO, L.TRECHO, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT GROUP_CONCAT(T.TEXTO ORDER BY T.SEGUNDO SEPARATOR ' ') FROM TRECHOS T WHERE T.VIDEO_ID = L.VIDEO_ID AND L.SEGUNDO IS NOT NULL AND T.SEGUNDO BETWEEN L.SEGUNDO - 40 AND L.SEGUNDO + 40) TRANSCRICAO FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = (SELECT X.TITULO FROM LIVROS_INDICADOS X WHERE X.ID = {{id}}) ORDER BY V.PUBLICADO_EM DESC, L.SEGUNDO LIMIT 6`, 'Onde um nome de livro foi dito: vídeo, minuto e transcrição ao redor'),
  S('livrosLista', `SELECT L.ID, COALESCE(LC.TITULO, L.TITULO) TITULO, COALESCE(LC.AUTOR, L.AUTOR) AUTOR, L.TRECHO, L.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(COALESCE(LC.TITULO, L.TITULO), ' ', COALESCE(LC.AUTOR, L.AUTOR, ''), ' ', COALESCE(L.TRECHO, '')) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) ORDER BY COALESCE(LC.TITULO, L.TITULO), V.PUBLICADO_EM DESC, L.ID LIMIT {{limit}} OFFSET {{offset}}`, 'Livros indicados nos vídeos, por canal e busca'),
  S('livrosTotais', `SELECT COUNT(*) N, COUNT(DISTINCT COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci) LIVROS, COUNT(DISTINCT L.VIDEO_ID) VIDEOS FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})`, 'Totais de indicações de livros'),
  S('livrosRelacao', `SELECT MIN(L.ID) ID, MIN(COALESCE(LC.TITULO, L.TITULO)) TITULO, COALESCE(MAX(LC.AUTOR), MAX(NULLIF(L.AUTOR, ''))) AUTOR, MAX(LC.STATUS_LEITURA) STATUS, COUNT(*) INDICACOES, COUNT(DISTINCT L.VIDEO_ID) VIDEOS, GROUP_CONCAT(DISTINCT C.NOME ORDER BY C.NOME SEPARATOR ', ') CANAIS FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(COALESCE(LC.TITULO, L.TITULO), ' ', COALESCE(LC.AUTOR, L.AUTOR, '')) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND LC.STATUS_LEITURA IS NULL) OR LC.STATUS_LEITURA = '{{status}}') AND ('{{titulo}}' = '' OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{titulo}}', '%')) AND ('{{autor}}' = '' OR COALESCE(LC.AUTOR, L.AUTOR, '') COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{autor}}', '%')) AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = 'LIVRO' AND FV.NOME COLLATE utf8mb4_0900_ai_ci = COALESCE(LC.TITULO, L.TITULO))) GROUP BY COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci ORDER BY IF('{{ordem}}' = 'az', 0, COUNT(DISTINCT L.VIDEO_ID)) DESC, TITULO LIMIT {{limit}} OFFSET {{offset}}`, 'Relação compilada dos livros indicados: um por título, com autor, vídeos e canais'),
  S('livrosDoTitulo', `SELECT L.ID, COALESCE(LC.TITULO, L.TITULO) TITULO, COALESCE(LC.AUTOR, L.AUTOR) AUTOR, L.TRECHO, L.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = (SELECT COALESCE(C2.TITULO, X.TITULO) COLLATE utf8mb4_0900_ai_ci FROM LIVROS_INDICADOS X LEFT JOIN LIVROS_NOMES N2 ON N2.NOME = X.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO C2 ON C2.ID = N2.CATALOGO_ID WHERE X.ID = {{id}}) ORDER BY V.PUBLICADO_EM DESC, L.SEGUNDO`, 'Todas as vezes que um livro foi indicado'),
  S('nomeMusica', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, 'MUSICA', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE ESTADO = 'MUSICA', CATALOGO_ID = NULL`, 'Marca um nome como música, álbum ou banda'),
  S('outrosSubtipo', `UPDATE LIVROS_NOMES SET SUBTIPO = NULLIF('{{subtipo}}', '') WHERE ID = {{id}}`, 'Define se um audiovisual é filme, série, documentário ou jogo'),
  S('nomeTipoPorNome', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, SUBTIPO, CRIADO_EM) SELECT MIN(L.TITULO), '{{estado}}', 'Decidido pela pessoa', NULLIF('{{subtipo}}', ''), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE '{{padrao}}' GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci LIMIT 1 ON DUPLICATE KEY UPDATE ESTADO = '{{estado}}', CATALOGO_ID = NULL, SUBTIPO = VALUES(SUBTIPO)`, 'Manda um nome para música, filme ou série, ou texto sagrado, pelo nome'),
  S('nomeAudiovisual', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, 'AUDIOVISUAL', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE ESTADO = 'AUDIOVISUAL', CATALOGO_ID = NULL`, 'Marca um nome como filme, série ou vídeo'),
  S('outrosTotais', `SELECT ESTADO, COUNT(*) N FROM LIVROS_NOMES WHERE ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO') GROUP BY ESTADO`, 'Quantos nomes há em Músicas, Audiovisuais e Textos sagrados'),
  S('outrosLista', `SELECT N.ID, N.NOME, N.MOTIVO, N.CONFERIDO, N.CONF_NOTA, N.SUBTIPO, (SELECT COUNT(DISTINCT L.VIDEO_ID) FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})) VIDEOS, (SELECT MIN(L.ID) FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})) INDICADO_ID, S.STATUS FROM LIVROS_NOMES N LEFT JOIN ITENS_STATUS S ON S.TIPO = N.ESTADO AND S.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = '{{estado}}' AND ({{canalId}} = 0 OR EXISTS (SELECT 1 FROM LIVROS_INDICADOS LX JOIN VIDEOS VX ON VX.ID = LX.VIDEO_ID WHERE LX.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME AND VX.CANAL_ID = {{canalId}})) AND ('{{busca}}' = '' OR N.NOME LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND COALESCE(S.STATUS, '') = '') OR S.STATUS = '{{status}}') AND ('{{conf}}' = '' OR COALESCE(N.CONFERIDO, 'NOVO') = '{{conf}}') AND ('{{subtipo}}' = '' OR ('{{subtipo}}' = 'nenhum' AND N.SUBTIPO IS NULL) OR N.SUBTIPO = '{{subtipo}}') AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = N.ESTADO AND FV.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME)) ORDER BY (N.CONFERIDO = 'DUVIDA') DESC, IF('{{ordem}}' = 'az', 0, VIDEOS) DESC, N.NOME LIMIT {{limit}} OFFSET {{offset}}`, 'Nomes de músicas, audiovisuais ou textos sagrados citados nos vídeos'),
  S('itemStatusGravar', `INSERT INTO ITENS_STATUS (TIPO, NOME, STATUS) VALUES ('{{tipo}}', '{{nome}}', '{{status}}') ON DUPLICATE KEY UPDATE STATUS = '{{status}}'`, 'Marca a situação de uma música, audiovisual ou texto sagrado'),
  S('sagradoObras', `SELECT O.OBRA NOME, COUNT(DISTINCT V.ID) VIDEOS, COUNT(DISTINCT O.NOME) PARTES, MAX(S.STATUS) STATUS FROM (SELECT N.ID, N.NOME, COALESCE(M.OBRA, N.NOME) OBRA FROM LIVROS_NOMES N LEFT JOIN OBRA_DE M ON M.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = 'SAGRADO') O LEFT JOIN LIVROS_INDICADOS L ON L.TITULO COLLATE utf8mb4_0900_ai_ci = O.NOME LEFT JOIN VIDEOS V ON V.ID = L.VIDEO_ID AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) LEFT JOIN ITENS_STATUS S ON S.TIPO = 'SAGRADO' AND S.NOME COLLATE utf8mb4_0900_ai_ci = O.OBRA WHERE ({{canalId}} = 0 OR V.ID IS NOT NULL) AND ('{{busca}}' = '' OR O.OBRA LIKE CONCAT('%', '{{busca}}', '%') OR O.NOME LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND COALESCE(S.STATUS, '') = '') OR S.STATUS = '{{status}}') AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = 'SAGRADO' AND FV.NOME COLLATE utf8mb4_0900_ai_ci = O.OBRA)) GROUP BY O.OBRA ORDER BY IF('{{ordem}}' = 'az', 0, COUNT(DISTINCT V.ID)) DESC, O.OBRA LIMIT {{limit}} OFFSET {{offset}}`, 'Textos sagrados agrupados por obra'),
  S('sagradoPartes', `SELECT O.ID, O.NOME, COUNT(DISTINCT V.ID) VIDEOS, MIN(CASE WHEN V.ID IS NOT NULL THEN L.ID END) INDICADO_ID FROM (SELECT N.ID, N.NOME, COALESCE(M.OBRA, N.NOME) OBRA FROM LIVROS_NOMES N LEFT JOIN OBRA_DE M ON M.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = 'SAGRADO') O LEFT JOIN LIVROS_INDICADOS L ON L.TITULO COLLATE utf8mb4_0900_ai_ci = O.NOME LEFT JOIN VIDEOS V ON V.ID = L.VIDEO_ID AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = '{{obra}}' GROUP BY O.ID, O.NOME ORDER BY VIDEOS DESC, O.NOME`, 'Partes e grafias de uma obra sagrada'),
  S('sagradoJuntar', `INSERT INTO OBRA_DE (NOME, OBRA) VALUES ('{{nome}}', '{{obra}}') ON DUPLICATE KEY UPDATE OBRA = '{{obra}}'`, 'Junta um nome a uma obra sagrada'),
  S('sagradoSeparar', `DELETE FROM OBRA_DE WHERE NOME = '{{nome}}'`, 'Tira um nome do grupo de uma obra'),
  S('nomeSagrado', `INSERT INTO LIVROS_NOMES (NOME, ESTADO, MOTIVO, CRIADO_EM) SELECT X.TITULO, 'SAGRADO', 'Decidido pela pessoa', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM LIVROS_INDICADOS X WHERE X.ID = {{id}} ON DUPLICATE KEY UPDATE ESTADO = 'SAGRADO'`, 'Marca um nome como texto sagrado ou clássico'),
  S('outrosEditar', `UPDATE LIVROS_NOMES SET CONFERIDO = IF('{{estado}}' = 'PENDENTE', NULL, 'ACEITO'), ESTADO = '{{estado}}', MOTIVO = NULLIF(LEFT('{{motivo}}', 300), ''), CATALOGO_ID = NULL WHERE ID = {{id}} AND ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO') AND '{{estado}}' IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO', 'PENDENTE')`, 'Muda o tipo de um nome (música, audiovisual, texto sagrado ou voltar para validar) e a nota'),
  S('outrosAceitar', `UPDATE LIVROS_NOMES SET CONFERIDO = 'ACEITO' WHERE ID = {{id}} AND ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO')`, 'A pessoa aceita a conferência de um nome de música, audiovisual ou texto sagrado'),
  S('outrosFila', `SELECT N.ID, N.NOME, N.ESTADO, (SELECT MAX(L.TRECHO) FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME) TRECHO, (SELECT MAX(NULLIF(L.AUTOR, '')) FROM LIVROS_INDICADOS L WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME) AUTOR FROM LIVROS_NOMES N WHERE N.ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO') AND N.CONFERIDO IS NULL ORDER BY N.ID LIMIT {{limit}}`, 'Nomes de música, audiovisual e texto sagrado ainda não conferidos pela IA'),
  S('outrosConferirGravar', `UPDATE LIVROS_NOMES SET CONFERIDO = '{{conferido}}', CONF_NOTA = NULLIF(LEFT('{{nota}}', 300), '') WHERE ID = {{id}} AND CONFERIDO IS NULL AND ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO')`, 'Grava o resultado da conferência da IA (OK ou dúvida) sem mexer no que a pessoa já aceitou'),
  S('outrosVoltar', `UPDATE LIVROS_NOMES SET ESTADO = 'PENDENTE' WHERE ID = {{id}} AND ESTADO IN ('MUSICA', 'AUDIOVISUAL', 'SAGRADO')`, 'Devolve um nome para Validar entradas'),
  S('favItemMarcar', `INSERT IGNORE INTO ITENS_FAVORITOS (TIPO, NOME, CRIADO_EM) VALUES ('{{tipo}}', '{{nome}}', DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s'))`, 'Marca um livro, música ou audiovisual como favorito'),
  S('favItemTirar', `DELETE FROM ITENS_FAVORITOS WHERE TIPO = '{{tipo}}' AND NOME = '{{nome}}'`, 'Tira um item dos favoritos'),
  S('favItensTipo', `SELECT NOME FROM ITENS_FAVORITOS WHERE TIPO = '{{tipo}}'`, 'Nomes favoritos de um tipo'),
  S('favItensLista', `SELECT F.NOME, (SELECT COUNT(DISTINCT L.VIDEO_ID) FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID WHERE (COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = F.NOME OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci IN (SELECT O.NOME COLLATE utf8mb4_0900_ai_ci FROM OBRA_DE O WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = F.NOME))) VIDEOS, (SELECT MAX(COALESCE(LC.AUTOR, L.AUTOR)) FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID WHERE (COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = F.NOME OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci IN (SELECT O.NOME COLLATE utf8mb4_0900_ai_ci FROM OBRA_DE O WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = F.NOME))) AUTOR FROM ITENS_FAVORITOS F WHERE F.TIPO = '{{tipo}}' ORDER BY F.NOME`, 'Meus favoritos: livros, músicas ou audiovisuais'),
  S('favVideosLista', `SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, C.NOME CANAL FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.FAVORITO = 1 AND V.STATUS <> 'FORA' ORDER BY V.PUBLICADO_EM DESC LIMIT 300`, 'Meus favoritos: vídeos'),
  S('favContagens', `SELECT (SELECT COUNT(*) FROM VIDEOS WHERE FAVORITO = 1 AND STATUS <> 'FORA') VIDEOS, (SELECT COUNT(*) FROM PRATICAS WHERE FAVORITA = 1) PRATICAS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'LIVRO') LIVROS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'MUSICA') MUSICAS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'AUDIOVISUAL') AUDIOVISUAIS, (SELECT COUNT(*) FROM ITENS_FAVORITOS WHERE TIPO = 'SAGRADO') SAGRADOS`, 'Meus favoritos: quantos de cada tipo'),
];
